package com.weearntogether.play

import android.app.Activity
import android.os.Bundle
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.widget.*
import kotlin.random.Random

class MainActivity : Activity() {
    private val navy=Color.rgb(7,12,31); private val panel=Color.rgb(18,27,58); private val purple=Color.rgb(105,70,230); private val blue=Color.rgb(32,116,232); private val gold=Color.rgb(255,197,77)
    private lateinit var root:LinearLayout; private var round=0; private var correct=0
    private val loyalty by lazy { LoyaltyProgress(this) }
    private val questions=listOf(Triple("Sa ditë ka një javë?",listOf("5","7","9","10"),1),Triple("Sa është 6 × 7?",listOf("36","42","48","56"),1),Triple("Cili planet quhet Planeti i Kuq?",listOf("Venusi","Marsi","Jupiteri","Saturni"),1),Triple("Cili është oqeani më i madh?",listOf("Atlantiku","Indian","Paqësori","Arktiku"),2),Triple("Sa brinjë ka trekëndëshi?",listOf("3","4","5","6"),0),Triple("Cila është kryeqyteti i Francës?",listOf("Roma","Parisi","Berlini","Vjena"),1),Triple("Sa minuta ka një orë?",listOf("30","45","60","90"),2),Triple("Cili është simboli kimik i ujit?",listOf("CO2","O2","H2O","NaCl"),2),Triple("Sa është 12 + 15?",listOf("25","26","27","28"),2),Triple("Cila gjuhë flitet kryesisht në Brazil?",listOf("Spanjisht","Portugalisht","Italisht","Frëngjisht"),1))
    private val profile by lazy{getSharedPreferences("wet_guest_profile",MODE_PRIVATE)}
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(profile.contains("guest_id"))home()else welcome()}
    private fun welcome(){layout("Mirë se vjen");text("WE EARN TOGETHER",15,gold);text("Luaj. Përparoi. Zhblloko sfida.",24);text("Krijo profilin lokal për të ruajtur progresin.",16,Color.LTGRAY);val nickname=EditText(this).apply{hint="Emri në lojë";setSingleLine(true);setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);setPadding(28,20,28,20);background=rounded(panel,28f);filters=arrayOf(android.text.InputFilter.LengthFilter(24))};root.addView(nickname,LinearLayout.LayoutParams(-1,110).apply{bottomMargin=22});button("VAZHDO"){val n=nickname.text.toString().trim().ifBlank{"Lojtar"};profile.edit().putString("display_name",n).putString("guest_id",java.util.UUID.randomUUID().toString()).putLong("created_at",System.currentTimeMillis()).apply();home()}}
    private fun rounded(color:Int,r:Float)=GradientDrawable().apply{setColor(color);cornerRadius=r}
    private fun gradient()=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(purple,blue)).apply{cornerRadius=30f}
    private fun layout(title:String){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(26,42,26,28);setBackgroundColor(navy)};val scroll=ScrollView(this).apply{isFillViewport=true;addView(root)};setContentView(scroll);if(title.isNotEmpty())text(title,30)}
    private fun text(s:String,size:Int=17,color:Int=Color.WHITE){root.addView(TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);setPadding(4,10,4,10);if(size>=23)setTypeface(null,Typeface.BOLD)})}
    private fun button(label:String,action:()->Unit){val b=Button(this).apply{text=label;textSize=16f;isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);background=gradient();setOnClickListener{action()}};root.addView(b,LinearLayout.LayoutParams(-1,112).apply{bottomMargin=14})}
    private fun gameCard(title:String,subtitle:String,badge:String,action:()->Unit){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(26,22,26,22);background=rounded(panel,34f);isClickable=true;setOnClickListener{action()}};box.addView(TextView(this).apply{text=badge;textSize=13f;setTextColor(gold);setTypeface(null,Typeface.BOLD)});box.addView(TextView(this).apply{text=title;textSize=23f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);setPadding(0,8,0,5)});box.addView(TextView(this).apply{text=subtitle;textSize=14f;setTextColor(Color.LTGRAY)});root.addView(box,LinearLayout.LayoutParams(-1,155).apply{bottomMargin=14})}
    private fun home(){layout("");val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};top.addView(TextView(this).apply{text="WE EARN TOGETHER";textSize=18f;setTextColor(gold);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,70,1f));top.addView(Button(this).apply{text=profile.getString("display_name","Lojtar");isAllCaps=false;setTextColor(Color.WHITE);background=rounded(panel,26f);setOnClickListener{account()}},LinearLayout.LayoutParams(250,70));root.addView(top);text("PLAY HUB",32);text("Zgjidh lojën dhe ngjitu në renditje.",16,Color.LTGRAY);val stats=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=rounded(panel,30f);setPadding(16,15,16,15)};stats.addView(TextView(this).apply{text="${loyalty.points}\nPIKË";gravity=Gravity.CENTER;textSize=17f;setTextColor(gold);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,100,1f));stats.addView(TextView(this).apply{text="${loyalty.currentStreak}\nSTREAK";gravity=Gravity.CENTER;textSize=17f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,100,1f));stats.addView(TextView(this).apply{text="${loyalty.todayGames}/${loyalty.dailyGoal}\nSOT";gravity=Gravity.CENTER;textSize=17f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,100,1f));root.addView(stats,LinearLayout.LayoutParams(-1,130).apply{bottomMargin=24});text("FEATURED",15,gold);gameCard("BUBBLE SHOOTER","Gjuajtje e shpejtë • nivele • rekord","ARCADE"){bubbleShooter()};gameCard("BLOCK PUZZLE","Strategji • kombinime • progres","PUZZLE"){blockPuzzle()};text("TË GJITHA LOJËRAT",15,gold);gameCard("2048","Bashko numrat dhe arrij rekordin","LOGIC"){merge2048()};gameCard("QUIZ ARENA","10 pyetje • rezultat i menjëhershëm","CHALLENGE"){round=0;correct=0;question()};gameCard("MEMORY","Gjej çiftet me sa më pak lëvizje","BRAIN"){memory()};gameCard("MATH RUSH","10 sfida të shpejta matematikore","SPEED"){mathGame()};button("PROGRESI IM"){progressDashboard()}}
    private fun account(){layout("Profili");text(profile.getString("display_name","Lojtar")?:"Lojtar",24,gold);text("ID lokale: "+(profile.getString("guest_id","")?:"").take(8).uppercase(),14,Color.LTGRAY);val e=EditText(this).apply{setText(profile.getString("display_name","Lojtar"));setTextColor(Color.WHITE);setSingleLine(true);background=rounded(panel,26f);setPadding(24,10,24,10)};root.addView(e,LinearLayout.LayoutParams(-1,100).apply{bottomMargin=16});button("Ruaj emrin"){val n=e.text.toString().trim();if(n.isNotEmpty()){profile.edit().putString("display_name",n).apply();account()}};button("Progresi"){progressDashboard()};button("Kthehu"){home()}}
    private fun progressDashboard(){layout("Progresi");text("${loyalty.points} PIKË",30,gold);text("Lojëra: ${loyalty.gamesPlayed}   •   Streak: ${loyalty.currentStreak}   •   Rekord: ${loyalty.bestStreak}",17);val done=loyalty.todayGames.coerceAtMost(loyalty.dailyGoal);text("SFIDA DITORE",16,gold);text("Përfundo ${loyalty.dailyGoal} sesione: $done/${loyalty.dailyGoal}",18);val bar=ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=loyalty.dailyGoal;progress=done};root.addView(bar,LinearLayout.LayoutParams(-1,34).apply{bottomMargin=18});if(loyalty.dailyClaimed)text("Bonusi ditor është marrë.",16,gold)else if(done>=loyalty.dailyGoal)button("Merr 100 pikë"){loyalty.claimDailyChallenge();progressDashboard()};button("PLAY HUB"){home()}}
    private fun recordSession(points:Int){loyalty.recordGameProgress(points)}
    private fun question(){if(round>=questions.size){result();return};layout("Quiz Arena");text("PYETJA ${round+1}/10   •   $correct PIKË",15,gold);val q=questions[round];text(q.first,23);q.second.forEachIndexed{i,a->button(a){if(i==q.third)correct++;round++;question()}}}
    private fun result(){recordSession(10+correct*2);layout("Rezultati");text("$correct / 10",32,gold);button("Luaj përsëri"){round=0;correct=0;question()};button("Play Hub"){home()}}
    private fun bubbleShooter(){layout("Bubble Shooter");text("Syno • gjuaj • pastro tabelën. Prek topin 'Tjetra' për ta ndërruar.",15,gold);val game=BubbleShooterView(this);root.addView(game,LinearLayout.LayoutParams(-1,1350));button("Rifillo"){game.restart()};button("Play Hub"){home()}}
    private fun merge2048(){layout("2048");val game=Merge2048View(this);root.addView(game,LinearLayout.LayoutParams(-1,1100));button("Rifillo"){game.restart()};button("Play Hub"){home()}}
    private fun blockPuzzle(){layout("Block Puzzle");val game=BlockPuzzleView(this);root.addView(game,LinearLayout.LayoutParams(-1,1350));button("Rifillo"){game.restart()};button("Play Hub"){home()}}
    private var memoryCards=mutableListOf<String>();private var memoryOpened=mutableListOf<Int>();private var memoryMatched=mutableSetOf<Int>();private var memoryMoves=0
    private fun memory(){memoryCards=(listOf("A","B","C","D","E","F")+listOf("A","B","C","D","E","F")).shuffled().toMutableList();memoryOpened.clear();memoryMatched.clear();memoryMoves=0;renderMemory()}
    private fun renderMemory(){layout("Memory");text("Lëvizje $memoryMoves   •   Çifte ${memoryMatched.size/2}/6",16,gold);if(memoryMatched.size==memoryCards.size){recordSession((40-memoryMoves).coerceAtLeast(10));text("PËRFUNDUAR",28,gold);button("Luaj përsëri"){memory()};button("Play Hub"){home()};return};for(r in 0 until 3){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};root.addView(row);for(c in 0 until 4){val i=r*4+c;val revealed=i in memoryOpened||i in memoryMatched;val card=Button(this).apply{text=if(revealed)memoryCards[i]else"•";textSize=25f;setTextColor(Color.WHITE);background=rounded(if(revealed)purple else panel,20f);isEnabled=i !in memoryMatched;setOnClickListener{if(i in memoryOpened||memoryOpened.size>=2)return@setOnClickListener;memoryOpened.add(i);if(memoryOpened.size==2){memoryMoves++;val a=memoryOpened[0];val b=memoryOpened[1];if(memoryCards[a]==memoryCards[b]){memoryMatched.add(a);memoryMatched.add(b);memoryOpened.clear();renderMemory()}else{renderMemory();android.os.Handler(mainLooper).postDelayed({memoryOpened.clear();renderMemory()},650)}}else renderMemory()}};row.addView(card,LinearLayout.LayoutParams(0,135,1f).apply{setMargins(5,5,5,5)})}};button("Play Hub"){home()}}
    private var mathRound=0;private var mathScore=0
    private fun mathGame(){mathRound=0;mathScore=0;nextMath()}
    private fun nextMath(){if(mathRound==10){recordSession(10+mathScore*2);layout("Math Rush");text("$mathScore / 10",32,gold);button("Luaj përsëri"){mathGame()};button("Play Hub"){home()};return};val a=Random.nextInt(2,21);val b=Random.nextInt(2,13);val answer=a*b;val choices=(listOf(answer)+generateSequence{answer+Random.nextInt(-20,21)}.filter{it>0&&it!=answer}.distinct().take(3).toList()).shuffled();layout("Math Rush");text("SFIDA ${mathRound+1}/10   •   $mathScore PIKË",15,gold);text("$a × $b = ?",32);choices.forEach{v->button(v.toString()){if(v==answer)mathScore++;mathRound++;nextMath()}}}
}
